-- Cadastro dos produtos do Cardápio Paggio (PDF). Só insere se não existir produto de mesmo nome e preço.
do $$
declare it jsonb; g record; cid uuid; pid uuid; fid uuid; iid uuid; gid uuid; ord int := 0; n int := 0;
begin
  for g in select * from jsonb_each_text('{"Sobremesas": 8, "Bebidas": 9, "Chopp e cervejas": 10, "Caipirinhas": 11, "Drinks": 12, "Doses": 13, "Vinhos": 14}'::jsonb) loop
    insert into checklist.pdv_categorias(nome,ordem) select g.key, g.value::int where not exists (select 1 from checklist.pdv_categorias where lower(nome)=lower(g.key));
  end loop;
  for g in select * from jsonb_each('{"Sabor do suco de frutas": ["Morango", "Maracujá", "Abacaxi", "Abacaxi com hortelã", "Coco"], "Sabor do suco com leite": ["Morango", "Maracujá"], "Sabor do suco Prats": ["Laranja", "Uva"], "Sabor do Sucos e Amor": ["Laranja", "Caju", "Limão", "Maracujá", "Uva"], "Sabor da soda italiana": ["Limão siciliano", "Frutas vermelhas", "Framboesa", "Tangerina"]}'::jsonb) loop
    if not exists (select 1 from checklist.pdv_grupos_opcoes where nome=g.key) then
      insert into checklist.pdv_grupos_opcoes(nome,tipo,min_escolhas,max_escolhas) values (g.key,'informacao',1,1) returning id into gid;
      insert into checklist.pdv_opcoes(grupo_id,nome,preco_adicional,ordem) select gid, v, 0, o-1 from jsonb_array_elements_text(g.value) with ordinality t(v,o);
    end if;
  end loop;
  for it in select * from jsonb_array_elements('[{"c": "Entradas", "n": "Salada tropical", "p": 34.9, "t": "p", "d": "cozinha"}, {"c": "Tábuas e petiscos", "n": "Porção de amendoim salgado", "p": 14.9, "t": "p", "d": "cozinha"}, {"c": "Tábuas e petiscos", "n": "Isca de frango", "p": 49.9, "t": "p", "d": "cozinha"}, {"c": "Tábuas e petiscos", "n": "Isca de tilápia", "p": 59.9, "t": "p", "d": "cozinha"}, {"c": "Tábuas e petiscos", "n": "Mini pastéis — queijo", "p": 49.9, "t": "p", "d": "cozinha"}, {"c": "Tábuas e petiscos", "n": "Mini pastéis — queijo e alho-poró", "p": 54.9, "t": "p", "d": "cozinha"}, {"c": "Tábuas e petiscos", "n": "Mini pastéis — carne", "p": 54.9, "t": "p", "d": "cozinha"}, {"c": "Tábuas e petiscos", "n": "Mix de pastel", "p": 44.9, "t": "p", "d": "cozinha"}, {"c": "Tábuas e petiscos", "n": "Polenta frita", "p": 44.9, "t": "p", "d": "cozinha"}, {"c": "Pratos individuais", "n": "Paggio Fit — tilápia", "p": 54.9, "t": "p", "d": "cozinha"}, {"c": "Pratos individuais", "n": "Paggio Fit — ancho", "p": 54.9, "t": "p", "d": "cozinha"}, {"c": "Pratos individuais", "n": "Paggio Fit — salmão", "p": 74.9, "t": "p", "d": "cozinha"}, {"c": "Pratos individuais", "n": "Parmegiana de frango", "p": 54.9, "t": "p", "d": "cozinha"}, {"c": "Pratos individuais", "n": "Talharim ao molho de tomates frescos com filé mignon", "p": 74.9, "t": "p", "d": "cozinha"}, {"c": "Pratos individuais", "n": "Prato kids — filé mignon", "p": 49.9, "t": "p", "d": "cozinha"}, {"c": "Pratos individuais", "n": "Prato kids — frango", "p": 29.9, "t": "p", "d": "cozinha"}, {"c": "Risotos", "n": "Risoto de salmão e tomate confit", "p": 74.9, "t": "p", "d": "cozinha"}, {"c": "Sobremesas", "n": "Torta Snickers", "p": 19.9, "t": "p", "d": "cozinha"}, {"c": "Sobremesas", "n": "Torta cheesecake de goiabada", "p": 14.9, "t": "p", "d": "cozinha"}, {"c": "Sobremesas", "n": "Pudim", "p": 19.9, "t": "p", "d": "cozinha"}, {"c": "Bebidas", "n": "Suco de frutas", "p": 12.9, "t": "g:Sabor do suco de frutas"