s", "p": 11.9, "t": "r", "d": "bar"}, {"c": "Chopp e cervejas", "n": "Long neck Stella Pure Gold", "p": 12.9, "t": "r", "d": "bar"}, {"c": "Chopp e cervejas", "n": "Corona 600ml", "p": 18.9, "t": "r", "d": "bar"}, {"c": "Chopp e cervejas", "n": "Stella Pure Gold 600ml", "p": 18.9, "t": "r", "d": "bar"}, {"c": "Chopp e cervejas", "n": "Stella Artois 600ml", "p": 16.9, "t": "r", "d": "bar"}, {"c": "Chopp e cervejas", "n": "Original 600ml", "p": 15.9, "t": "r", "d": "bar"}, {"c": "Chopp e cervejas", "n": "Spaten 600ml", "p": 15.9, "t": "r", "d": "bar"}, {"c": "Chopp e cervejas", "n": "CDB", "p": 5.0, "t": "r", "d": "bar"}, {"c": "Caipirinhas", "n": "Caipirinha de limão", "p": 22.9, "t": "d", "d": "bar"}, {"c": "Caipirinhas", "n": "Caipirinha de kiwi com morango", "p": 22.9, "t": "d", "d": "bar"}, {"c": "Caipirinhas", "n": "Caipirinha de limão siciliano", "p": 22.9, "t": "d", "d": "bar"}, {"c": "Caipirinhas", "n": "Caipirinha de 3 limões", "p": 22.9, "t": "d", "d": "bar"}, {"c": "Caipirinhas", "n": "Caipirinha de morango", "p": 22.9, "t": "d", "d": "bar"}, {"c": "Caipirinhas", "n": "Caipirinha de kiwi", "p": 22.9, "t": "d", "d": "bar"}, {"c": "Caipirinhas", "n": "Caipirinha de tangerina com pimenta dedo-de-moça", "p": 22.9, "t": "d", "d": "bar"}, {"c": "Caipirinhas", "n": "Caipirinha de tangerina", "p": 22.9, "t": "d", "d": "bar"}, {"c": "Caipirinhas", "n": "Caipirinha de maracujá", "p": 22.9, "t": "d", "d": "bar"}, {"c": "Caipirinhas", "n": "Caipirinha de coco", "p": 22.9, "t": "d", "d": "bar"}, {"c": "Caipirinhas", "n": "Caipirinha de abacaxi", "p": 22.9, "t": "d", "d": "bar"}, {"c": "Drinks", "n": "Gin tradicional com especiarias", "p": 29.9, "t": "d", "d": "bar"}, {"c": "Drinks", "n": "Gin Tropical", "p": 34.9, "t": "d", "d": "bar"}, {"c": "Drinks", "n": "Gin Blueberry", "p": 39.9, "t": "d", "d": "bar"}, {"c": "Drinks", "n": "Aperol Spritz", "p": 34.9, "t": "d", "d": "bar"}, {"c": "Drinks", "n": "Gin com abacaxi", "p": 39.9, "t": "d", "d": "bar"}, {"c": "Drinks", "n": "Gin com purê de morango e hortelã", "p": 39.9, "t": "d", "d": "bar"}, {"c": "Drinks", "n": "Gin com morango, abacaxi e manjericão", "p": 34.9, "t": "d", "d": "bar"}, {"c": "Drinks", "n": "Gin com limão siciliano", "p": 29.9, "t": "d", "d": "bar"}, {"c": "Drinks", "n": "Gin do Bife", "p": 74.9, "t": "d", "d": "bar"}, {"c": "Drinks", "n": "Buck''s Fizz", "p": 34.9, "t": "d", "d": "bar"}, {"c": "Drinks", "n": "Negroni", "p": 39.9, "t": "d", "d": "bar"}, {"c": "Drinks", "n": "Fitzgerald", "p": 34.9, "t": "d", "d": "bar"}, {"c": "Drinks", "n": "Licor 43 com café", "p": 49.9, "t": "d", "d": "bar"}, {"c": "Drinks", "n": "Licor 43 com café e limão", "p": 49.9, "t": "d", "d": "bar"}, {"c": "Drinks", "n": "Licor 43 com limão", "p": 39.9, "t": "d", "d": "bar"}, {"c": "Drinks", "n": "Licor 43 com maracujá", "p": 44.9, "t": "d", "d": "bar"}, {"c": "Drinks", "n": "Licor 43 com maracujá e Red Bull Tropical", "p": 59.9, "t": "d", "d": "bar"}, {"c": "Drinks", "n": "Cozumel", "p": 24.9, "t": "d", "d": "bar"}, {"c": "Drinks", "n": "Mojito", "p": 24.9, "t": "d", "d": "bar"}, {"c": "Drinks", "n": "Combo Gin", "p": 199.9, "t": "d", "d": "bar"}, {"c": "Doses", "n": "Campari", "p": 19.9, "t": "d", "d": "bar"}, {"c": "Doses", "n": "Balena", "p": 34.9, "t": "d", "d": "bar"}, {"c": "Doses", "n": "Red Label", "p": 24.9, "t": "d", "d": "bar"}, {"c": "Doses", "n": "Absolut Vanilia", "p": 29.9, "t": "d", "d": "bar"}, {"c": "Doses", "n": "Black Label", "p": 29.9, "t": "d", "d": "bar"}, {"c": "Doses", "n": "Jack Daniel''s", "p": 29.9, "t": "d", "d": "bar"}, {"c": "Doses", "n": "Jack Daniel''s Honey", "p": 29.9, "t": "d", "d": "bar"}, {"c": "Vinhos", "n": "Vinho tinto Dante Robino Malbec", "p": 89.0, "t": "r", "d": "bar"}, {"c": "Vinhos", "n": "Vinho tinto Cabriz", "p": 129.9, "t": "r", "d": "bar"}, {"c": "Vinhos", "n": "Vinho branco Cabriz", "p": 129.9, "t": "r", "d": "bar"}, {"c": "Vinhos", "n": "Vinho rosé Cabriz", "p": 129.9, "t": "r", "d": "bar"}, {"c": "Vinhos", "n": "Vinho branco Novecento Blend de Brancas", "p": 89.9, "t": "r", "d": "bar"}, {"c": "Vinhos", "n": "Espumante Veuve Ambal", "p": 172.0, "t": "r", "d": "bar"}]'::jsonb) loop
    ord := ord + 10;
    if exists (select 1 from checklist.pdv_produtos where checklist.normalizar_pdv(nome)=checklist.normalizar_pdv(it->>'n') and preco=(it->>'p')::numeric) then continue; end if;
    select id into cid from checklist.pdv_categorias where lower(nome)=lower(it->>'c') limit 1;
    fid := null;
    if it->>'t'='r' then
      insert into checklist.insumos(nome,unidade,preco) values (it->>'n' || ' (revenda)','un',0) returning id into iid;
      insert into checklist.fichas(tipo,nome,rendimento,rendimento_unidade,porcoes,perda_pct,preco_venda) values ('prato',it->>'n',1,'un',1,0,(it->>'p')::numeric) returning id into fid;
      insert into checklist.ficha_itens(ficha_id,insumo_id,quantidade,unidade,ordem) values (fid,iid,1,'un',0);
    elsif it->>'n'='Soda italiana' then
      select id into fid from checklist.fichas where nome='Soda italiana' limit 1;
    end if;
    insert into checklist.pdv_produtos(categoria_id,ficha_id,nome,preco,destino,ordem,unidade) values (cid,fid,it->>'n',(it->>'p')::numeric,it->>'d',ord,'UN') returning id into pid;
    if (it->>'t') like 'g:%' then
      insert into checklist.pdv_produto_grupos(produto_id,grupo_id,ordem) select pid,id,0 from checklist.pdv_grupos_opcoes where nome=substr(it->>'t',3);
    end if;
    n := n + 1;
  end loop;
  raise notice 'inseridos: %', n;
end $$;
